-- GENERATED by `wfj generate` from data/quest/quest-0095.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [95034] = { "借り", "SepulcherのLumina Windsingerと話してください。", "知っておいてほしいのだけど、道中で私たちを襲ったのは、実はGnollsではなかったの。\n\n実際に襲ってきたのは、狼のような巨大な生き物で、今では「worgen」だと知っているわ。そいつは護衛たちを片づけて私に向かってきたけど、Banonがその前に身を投げ出したの。私はなんとか呪文を放って驚かせ、追い払ったけれど、Banonはもうひどく噛まれていた。彼は自分を置いていけと言い張ったけど、私は拒んだわ。\n\n足を引きずりながらここへ戻る途中で、gnollに見つかったの。その後に起きたことは、恐ろしかった……", nil, nil, 0x0ff7705c, 0x84784026, 0xdc6412d7, nil, nil, "...mm" },
  [95036] = { "Moon-Kissedの刃", "SepulcherのTrevan Rolと話し、彼が必要とする材料を届けてください。", "Trevanによれば、worgenはSilverpine Forestの住民にとって大きな脅威だそうよ。強くてしぶといけれど殺すことはできる。でも、中に一体だけ、得体の知れない魔法のせいでどうしても死んだままでいない奴がいるの。\n\n私たちを襲ったのはそいつよ。Old Fire-Eyeと呼ばれていて、仲間の中でも一番大きくて凶暴な奴なの。あいつを仕留めるには、特別な武器が必要になるわ。\n\nTrevanと話して。そんな武器を鍛えるのに必要なものの一覧を渡してくれるはずよ。", nil, nil, 0xe7da37a4, 0x4585e62b, 0xb4f5a29b, nil, nil, "...mm" },
  [95041] = { "データの溜め込み屋", "Gnomeregan各地からGnomeregan Archival Dataのカードを7枚集め、IronforgeのJemma Quikswitchに届けてください。", "Gnomereganから逃げる前に、うちの一族の記録を紙に写しておいたんだ。奥義工学の場の方程式、Second Warの潜水艦の船体設計、Grandma Quikswitchのチリのレシピ……僕らの最高の業績があのファイルに詰まってる。\n\nIronforgeに着いてから、荷物に穴が開いてるのに気づいたんだ！ パンチカードが何枚かなくなってて、それがないとデータがめちゃくちゃで復元できないんだよ。\n\nカードはGnomereganの外のどこかで、雪に埋もれてるはずなんだ。探してきてくれないかな？ 望み薄なのはわかってるんだけど……", nil, nil, 0x2ec708ec, 0xdde3bae7, 0xd738032b, nil, nil, "...mm" },
  [95042] = { "Kor Gemを求めて", "AshenvaleのUlric FrostveilにKor Gemを持って行って下さい。", "Forsakenのパラディンが……このAshenvaleに？面白い。\n\nそれで、Kor Gemを探しているのか？驚くことでもない。あれはAllianceのパラディンたちが魔法の武器や道具に力を込めるのに使うことがあるからな。堕ちたパラディンのお前だからといって、何が違う？\n\n本当にあの宝石が欲しいなら、北へ向かい、Blackfathom Deepsと呼ばれる廃墟へ行くことだ。宝石を今も使っているnagaは、その奥深くにいる。一人で行くな、{class}。", nil, nil, 0x5d353131, 0x653f65b8, 0xbb4e0ac5, nil, nil, "...mm" },
  [95065] = { "釣りの時間だ", "Shiny Baubleを$N1個とNightcrawlersを$N2個、Stormwindの港にいるGilbert Grayのところへ持って行ってください。", "なんという眺めだ……老いぼれが望める最高のものだよ。\n\n今は魚がよく食いついているんだが、餌がもう最後なんだ。まさか釣り道具の予備なんて持っていないだろうね？ いや、もちろんないよな、すまない。もう一度糸を垂らすことを考えたら嬉しくなって、どこへ行くにも道具を持ち歩く者なんてそうはいないってことに思い至らなかったよ。\n\n在庫の補充を手伝ってもらえないかな？ Catherine Lelandが、運河沿いのTrade Districtのすぐ西でいろいろな釣り道具を扱っている。老いぼれのGrayの使いだと言ってくれ。", nil, nil, 0x50ff1618, 0x1ca3ae56, 0x4f6c7d2d, nil, nil, "...mm" },
  [95111] = { "過小評価された才能", "Ottと話し、あなたの剣を鍛えてくれるよう頼む。", "Tarren MillにOttという武器の鍛冶屋がいる。誰に聞いても平凡な鍛冶屋で、旅人に簡素な剣を売っているそうだ。私も彼から剣を一振り買ったのだが、しばらくして手入れのためにundercityへ持って行くと、そこの鍛冶屋たちがその出来に驚いていた。名の知れた名工の作だと思ったらしいが、違う、ただのOttの作だったのだ。\n\nこのオークに、本当に特別なことをする機会を与えたい。材料をTarren MillのOttへ持って行き、この依頼を申し出てくれ。", nil, nil, 0x2c5a8af0, 0x57d2ed34, 0xb4029a86, nil, nil, "...mm" },
  [95125] = { "Ott's Masterwork", "Ottがあなたの剣を鍛えるのを見届ける。", "これは実に見事な素材だな、{class}。この剣を鍛えさせてくれるとは光栄だ。期待に応えられるといいんだが。\n\nさあ、少し下がっていてくれ。鍛造を始めるからな。", nil, nil, 0x2af2ae36, 0xa5330aaf, 0xa0a0368f, nil, nil, "...mm" },
  [95126] = { "Moonsilver Blade", "Ott's MasterworkをSilverpine ForestのTrevan Rolに届ける。", "これが剣だ。Trevanという名のパラディンに言われて来たと言ったな? 今度会ったら、この機会をくれた礼を伝えてくれ。誇りを持って行け、友よ。", nil, nil, 0x774c6075, 0xb9d5e27a, 0xac0b5a01, nil, nil, "...mm" },
  [95140] = { "Old Fire-Eye", "Moonsilver Bladeを使ってSilverpine ForestのOld-Fire Eyeを倒す。", "武器を手に入れたようだな、{class}。それがお前を裏切らぬよう祈っている。\n\n地元の者の話では、Old Fire-Eyeはここから南の広い範囲で狩りをしていて、たいていはGilneasの門の近くで見つかるそうだ。奴を見つけ、新しい剣で仕留めてくれ。それが済んだら戻ってこい。Windshaperたちの感謝を受けるだろう。", nil, nil, 0x1db24010, 0xdb7897c9, 0x2f1bb8e0, nil, nil, "...mm" },
  [95161] = { "愛していると忘れないで", "Blood-Stained LetterをDuskwoodのAvette Fellwoodに届けてください。", "Jeremy Heartweaverを探しているなら、Duskwoodにいる、彼の新しい養母Avette Fellwoodに話を聞くのが一番よ。優しい人でね。仕事の人手がもうひとり欲しいところだろうけど、孤児院にいるよりはましだわ。\n\nもし小さなJeremyに会ったら、みんなあの子のことを思っているって、必ず伝えてくれる？", nil, nil, 0x920a601f, 0xa5aac85c, 0x80f11769, nil, nil, "...mm" },
  [95189] = { "Crest of Lordaeron", "Crest of LordaeronをStormwind CityのLady Dena Kennedyに返してください。", "<Lordaeronの紋章が描かれた、風雨にさらされた紋章だ。王国の滅亡後に残った遺物はごくわずかなので、Stormwindの誰かがぜひとも手に入れたがるだろう。>", nil, nil, 0x98ec1516, 0xea3f7a39, 0x6f2a4873, nil, nil, "...mm" },
  [95195] = { "Bloodied Insignia", "Bloodied Insigniaを$N1個集め、Stormwind CityにいるGeneral Marcus Jonathanのところへ持って行ってください。", "<この古いAllianceの記章は、Lordaeronの兵士のものだったようだ。この遺跡には、きっと同じような勲章がたくさん眠っていて、生きている身内は返してもらえればありがたく思うだろう。>", nil, nil, 0xfb70dfc5, 0xf9dfef5a, 0x2c958367, nil, nil, "...mm" },
  [95204] = { "Crest of Lordaeron", "Crest of LordaeronをUndercityのOran Snakewritheに届けてください。", "<Lordaeronの紋章が描かれた、風雨にさらされた紋章だ。王国の滅亡後に残った遺物はごくわずかなので、Undercityの誰かがぜひとも手に入れたがるだろう。>", nil, nil, 0x98ec1516, 0x937c7b4b, 0x992e7722, nil, nil, "...mm" },
  [95212] = { "鞍に妥協なし", "Pristine Leopard Peltsを6枚集め、Amberstill Ranchに届けてください。", "Alterac遠征隊の増援に雄羊の隊を送る準備をしているんだが、鞍を作る材料が切れてしまったんだ。\n\n東にいる一番大きくて獰猛な豹の毛皮を集めて持ってきてくれ。あそこは身を切るような寒さだ。我らの部隊には、暖を取るための最高の毛皮こそふさわしい！", nil, nil, 0x07df31f7, 0x270babaf, 0xb5c3ab85, nil, nil, "...mm" },
  [95213] = { "Stolen Blasting Powder", "Empty Powder KegをGol'Bolar QuarryのQuarrymaster Thestenに届けてください。", "樽には刻印がある。\n\n発破用火薬 - 危険 - 取扱禁止 - 危険 - 採石場長の許可者のみ - 危険\n\ntroggがこれを持っているべきではないという嫌な予感がする。できるだけ早く採石場に報告した方がいいだろう。", nil, nil, 0x8848eca5, 0xd56ef55e, 0xf1f411df, nil, nil, "...mm" },
  [95214] = { "Stolen Blasting Powder", "Gol'Bolar Quarryの東にいるtroggからStolen Blasting Powderを$N1個取り戻し、Quarrymaster Thestenのところへ戻ってください。", "この樽には、King Magniの玉座の間を吹きさらしの中庭に変えてしまえるほどの火薬が入っていた。troggどもが火のつけ方に気づく前に、取り返さなきゃならん。", nil, nil, 0x8848eca5, 0x4fe59366, 0xcc857a5c, nil, nil, "...mm" },
  [95216] = { "新たな疫病", "UndercityのTheodore Griffsのために、Ruins of LordaeronのWitherfangからHighly Toxic Strainを手に入れてください。", "Undercityで最も重要な臓器、The Apothecariumへようこそ！ ここではAzerothの珍しい標本の中でも最も毒性の強いものを使って実験しているのです。\n\n今は機嫌がいいので、私の最新の研究について教えてあげましょう。どうやら、我らが麗しき街の上の廃墟に、特に毒の強い節足動物がうろついているらしいのです。その毒はアンデッドの肉さえも溶かすと言われています。なんと胸躍ることでしょう！\n\nこの話を確かめたいのです。もしその咬み傷で体が朽ちていくようなことがあれば、ぜひ見本をいただきたいですね。", nil, nil, 0xbf7a7e24, 0xec263960, 0x9214d563, nil, nil, "...mm" },
  [95217] = { "採石場の鍛冶屋", "Copper Barsを12本とToughened Boar Hidesを4枚集め、Frast Doknerに届けてください。", "鍛冶屋の仕事を学びたいってのか？ だったら、お互い助け合えるかもしれないな。\n\n補給品の輸送が遅れていて、野営地のあちこちを修理する材料が要るんだ。必要なものを持ってきてくれたら、俺の技をいくつか教えてやろう。悪くない話だろ？", nil, nil, 0xcf9ba453, 0x56fdeb4f, 0xd3803ca1, nil, nil, "...mm" },
  [95250] = { "忌まわしき怪物", "Ruins of LordaeronでHead of the Baronを手に入れ、Captain Trumanのもとへ持ち帰ってください。", "何の用だ、{race}？ 勝たねばならん戦があるのが見えんのか？\n\n主人はすでに戦いのただ中へ突撃していき、私には持ち場を守るよう命じられた。だが、もうかなりの時間が経っている。\n\nお前が戦場で10分も生き延びられるとは思えんが、その単純な頭の暇つぶしになるなら、Grand Marshalを探してみたらどうだ。お前がこれまで目にした中で最も背が高く、最も堂々とした英雄だ。見ればすぐにわかるだろう。", nil, nil, 0x83266151, 0xb8e0ac06, 0x0f67af09, nil, nil, "...mm" },
  [95314] = { "あのShadowvaleの緑の霊薬", "ShadowvaleでBottles of Whispering Elixirを$N1本集め、BrillにいるCarolai Aniseのところへ戻ってください。", "Scourgeの侵攻以前、人里離れたShadowvaleの村はWhispering Elixirで知られていた。Tyr's Fallにしか生えない薬草から蒸留されたその霊薬は、街で禁じられた後でさえ、薬師や神秘家、毒使いにまで求められていたんだ。\n\n何人もの買い手から、その霊薬が欲しいと頼まれている。西のWhispering Forestの奥深くにあるShadowvaleの廃墟へ行ってくれ。何本か取り戻してくれたら、たっぷり報酬を出す用意がある。", nil, nil, 0x62c6b7bf, 0xff6777a1, 0x5740e013, nil, nil, "...mm" },
  [95328] = { "Whispering Horror Residue", "Whispering Horror ResidueをUndercityのWar QuarterにいるFather Lankesterに届けてください。", "気は進まないものの、あなたは獣のうごめく残骸をこそげ取って集める。Undercityの誰かなら使い道があるかもしれない。", nil, nil, 0xb283ff1d, 0xa13a9b4c, 0x1336682a, nil, nil, "...mm" },
  [95349] = { "Earthen Ring", "Zephras Isleからスカイカッター船に乗ってMulgoreへ向かい、到着したらAlana Stormwalkerと話してください。", "カルトをめぐる最近の出来事でAzerothへ渡る予定が遅れ、しばらくはここValanaarに残らねばならない。代わりに、君と数人のWindshaperたちが我々の先遣隊となる。MulgoreではAlaana StormwalkerがWindshaperの到着を待っている。我々がここの用事を片付ける間、Azerothを探索してほしい。我々もすぐに合流する。\n\n準備ができたら、このロッジのすぐ外の桟橋へ行き、そこのskycutter船に乗ってくれ。\n\nBanu-Alah、{name}。", nil, nil, 0x28da0b16, 0xebfa2130, 0x76858aa9, nil, nil, "...mm" },
  [95350] = { "Azerothへようこそ", "Orgrimmarへ行き、Valley of WisdomにいるThrallと話してください。", "この下の世界は広い。そして新たな同盟者こそが、我々が生き延びる鍵だ。\n\nEarthen Ringは、志を同じくする誇り高き民の集まり、「Horde」の一員だ。近くのThunder Bluffの街もHordeの一部で、さらに東には首都Orgrimmarがある。\n\nThunder Bluffの中心にいるフライトマスターを訪ねてくれ。Orgrimmarまで飛ばしてくれるので、そこでWindshapersを代表して、Hordeの大族長Thrallと接触してほしい。風の導きがあらんことを、{name}。", nil, nil, 0x2f003d6f, 0x53ee86b6, 0xb4e4dfd7, nil, nil, "...mm" },
  [95494] = { "傷ついた誇りとライオンの皮", "BarrensのSavannah MatriarchsとSavannah Patriarchsから、Savannah Lion Hidesを6枚集めてください。", "剣の腕が立って、時間に余裕のある者に、ライオンの皮集めを手伝ってほしい。見知らぬ者にこんな助けを頼むのは誇りが傷つくが、最近脚を怪我してしまってな。治るまでは自分で狩りに出られる状態じゃないが、果たさねばならん約束がある。\n\nこのあたりでは、大きな奴ほどたいてい皮が上等だ。まずはそいつらから始めてくれ。", nil, nil, 0x5b2ff02d, 0xce49bfcd, 0x5cce729a, nil, nil, "...mm" },
  [95495] = { "隠者の皮なめし職人", "Bundle of Hidesを、BarrensのDry Hillsを見下ろす尾根にいる隠者に届けてください。", "この皮は、よく取引している皮なめし職人に届けるものだ。そいつはちょっとした世捨て人で、俺の後ろの尾根の頂上にひとりで住んでいる。今の俺には急な斜面を登るのは楽じゃないから、代わりに届けてくれたら恩に着る。\n\nああ、それと、その皮なめし職人の……見た目のことだが。驚かなくていい。見た目はああだが、危険はない。これは本当だと誓う。", nil, nil, 0xc91f6041, 0x2e6fcebc, 0xf3a9275e, nil, nil, "...mm" },
  [95507] = { "Vrangの獲物", "BarrensのSprung Trapsにある罠から、Trapped Gameを8つ集めてください。", "外に出ているついでに、俺の罠を見てきてくれるとすごく助かる。谷じゅうにばらまいてあるんだ。\n\nかかっている小さな獲物を持ってきてくれ。ただ、他の野生の動物には気をつけろよ。このあたりは、気を抜いていると危ないからな。", nil, nil, 0x56a6a9a8, 0xc7e5f7a1, 0xd203b57b, nil, nil, "...mm" },
  [95508] = { "招かれざる客", "Terry LongdrinkとKul Tirasの海兵隊との遭遇を、Waltonが生き延びられるよう手助けしてください。", "ああ、かつてはKul Tirasの海軍にいた。Lord AdmiralがTheramoreを奪ってDurotarでの作戦を始めた後、俺はそのやり方に……「異議」があってな。特に、民間人を処刑するやり方にだ。\n\n話にはまだ続きがあるんだが……待て……あれは何だ？\n\n男たちの一団が尾根を登ってくるぞ！", nil, nil, 0xaedbb4a0, 0xfb874c5b, 0x5b6957f0, nil, nil, "...mm" },
  [95621] = { "谷の異変", "壊されたキャラバンへ行き、Kul Tiransがなぜここにいるのかを探ってください。", "今朝、下の谷で何かを探している人間の一団を見つけた。ライフルのスコープでよく見てみたら、Kul Tirasの紋章をつけた兵士なのは明らかだった。\n\n俺からの仕事を引き受けてくれるなら、南の壊れた隊商のそばにある、そいつらの野営地へ行ってくれ。見つけた奴は殺して、なぜここにいるのか探ってくれ。", nil, nil, 0x389c29a3, 0xef54682f, 0xcaabc078, nil, nil, "...mm" },
  [95771] = { "闇の味", nil, nil, nil, nil, 0x8583a882, nil, nil, nil, nil, ".mmmm" },
  [95774] = { "彼女の名はOlgra", "quilboarを倒し、Mankrikの弔いのためにOlgra's Adornmentsを$N1個集めてください。", "私を救ってくれた治療師も、彼女を救うことはできなかった。彼女は戦いの中で死んだのだ。名はOlgra。私は決して彼女を忘れない。\n\n彼女の遺体に飾りはなかったのか？ 磨いた骨の宝飾をたくさん身につけていたのだが。\n\n彼女が倒れたあたりにいるRazormane Raidersを倒し、彼女の大切な作品を見つけてきてくれ！\n\n彼女を偲んで私が建てる記念碑に、それを添えるつもりだ。", nil, nil, 0xe0733c23, 0x64b2ed87, 0x1085cf6b, nil, nil, "...mm" },
  [95803] = { "誠意の証", "Rudolph Gelhardtの首をUndercityのSylvanas Windrunnerに届けてください。", "汚れた司令官の首を取った今、それをUndercityへ届けてもらいたい。Sylvanas Windrunnerは我々をひどく疑っていて、ほとんどあからさまに見下している。\n\nRudolph Gelhardtの首をDark Ladyに届けろ。我々が自分たちの家の始末は自分でつけ、Forsakenの繁栄に身を捧げていることを示すのだ。", nil, nil, 0x8a963535, 0x09f1d511, 0x27427458, nil, nil, "...mm" },
  [95805] = { "An'sheとMu'shaの恩寵", "香が10分で燃え尽きる前に、Smoldering Incenseを南東の丘にあるAn'sheとMu'shaの祠へ運んでください！", "太陽と月、An'sheとMu'shaは、精霊のようにこの世界の一部ではありません。けれどもその光は、私たちに命と導きと希望を与えてくれます。\n\n私たちは世界の精霊に敬意を払います。ですから、双子にも敬意を払うのです。\n\nあなたも敬意を示したいのなら、このくすぶるお香を持って、南東の丘にある祠へ届けてください。台地を見下ろす、quilboarの南にある祠です。お香が燃え尽きる前に祠にたどり着けるよう、急いでください。\n\n濡らしてはいけませんよ！", nil, nil, 0x1483f5df, 0x82228fe2, 0x52a83811, nil, nil, "...mm" },
  [95816] = { "参加させてくれ！", "記入済みの書類をRedridge MountainsのElaine Comptonに届けてください。", "熟練の職人の皆さま、ごきげんよう！\n\nこの用紙にご記入いただくと、Azeroth全土であなたの生産スキルの広告看板を掲げる、非独占的・取消可能・法的に限定された許可が得られます！\n\nご記入後は、手続き開始のため、お近くのAzeroth Commerce Authority支部のContract Coordinatorまでお持ちください。\n\n楽しい物作りを！", nil, nil, 0xe71188a6, 0xaef04737, 0x5eb40123, nil, nil, "...mm" },
  [95819] = { "参加させてくれ！", "記入済みの書類をThe BarrensのJornahに届けてください。", "熟練の職人の皆さま、ごきげんよう！\n\nこの用紙にご記入いただくと、Azeroth全土であなたの生産スキルの広告看板を掲げる、非独占的・取消可能・法的に限定された許可が得られます！\n\nご記入後は、手続き開始のため、お近くのDurotar Supply & LogisticsのContract Coordinatorまでお持ちください。\n\n楽しい物作りを！", nil, nil, 0xe71188a6, 0x73fcb0bd, 0xb6355654, nil, nil, "...mm" },
  [95883] = { "Tortured Soul", "Silverpine ForestのBeren's Perilにいる近くのアンデッドから、Tortured Soulを一つ手に入れてください。", "<急ごしらえの儀式の支度が、無造作に祭壇の上に集められている。書き付けの切れ端によれば、すべて揃っているようだ。足りないのは血の捧げ物と、Tortured Soulだけだ。\n\n周りのアンデッドは十分に苦しんでいるように見える。探しているものを持っているかもしれない。>", nil, nil, 0xb60b70e3, 0x0d080853, 0x972297ea, nil, nil, "...mm" },
  [95884] = { "捧げ物の石", "Silverpine ForestのBeren's PerilでOffering Stoneを見つけてください。", "<書き付けの切れ端はほとんど判読できない。だが、まだ読める部分には、捧げ物の支度についての覚え書きがある。\n\n捧げ物の石と、儀式のことが書かれている。\n\nこの捧げ物の石は、近くで見つかるかもしれない。>", nil, nil, 0xa6de587b, 0x975b0b28, 0x838aeea9, nil, nil, "...mm" },
  [95885] = { "血の捧げ物", "Tortured Soulを使い、Beren's PerilのOffering Stoneで血の捧げ物をしてください。", "<残るは血の捧げ物だけだ。\n\n書き付けの切れ端には「自ら望む生贄」とあった。\n\n強い恐怖が押し寄せてくる。>", nil, nil, 0x3785a093, 0x7d15beec, 0xb34b8754, nil, nil, "...mm" },
  [95981] = { "道の見張り", "SepulcherにいるShadow Priest Allisterのために、Dalaran Wizardを$N1人とDalaran Watcherを$N2人倒してください。", "奴らのペンダントを奪うのは最初の一歩にすぎない。もしKirin Torが本当にDalaranから遺物を絶えず送り込んでいるのなら、元から断たねばならん。\n\nAmbermillの周りの道で、Dalaranの魔術師と監視者を探せ。奴らのせいで、あまりにも長いあいだ我らの国境を自由に行き来されてきた。奴らの数を減らせれば、そもそもこのペンダントがSilverpine Forestに入ってくるのを止められるはずだ。", nil, nil, 0xda0a241c, 0x94f2addc, 0x6d26148a, nil, nil, "...mm" },
  [95998] = { "大自然", "チャット欄に/sitと入力してSam's Basic Campfireのそばに座り、Boosted Restのバフを受けるまで待ってください。", "やあどうも、{class}。あんた、冒険者らしい顔つきをしてるね。いいことだ。世の中には、富と栄光を求める俺たちみたいな落ち着きのない連中がもっと必要なんだよ。\n\n外の世界は広くてね、うまくやっていくには荒野で生き抜く術を身につけなきゃならない。あんたのアウトドアの腕前がどれほどかは知らないが、覚える気があるなら、ひとつふたつ教えてやれると思うよ。\n\n火のそばに座って、楽にしてくれ。順を追って説明するよ。", nil, nil, 0x561c5fa2, 0xc83659fa, 0xd463b94a, nil, nil, "...mm" },
  [95999] = { "お尋ね者：Incinerator Gar'im", "Broken Staff of Incinerator Gar'imをLakeshireのMagistrate Solomonに届けてください。", "手配書！ Incinerator Gar'im、Render's Valleyに侵攻したオークの一団の首領。Stonewatch KeepのBlackrockと手を組んでいるとされる。\n\nIncinerator Gar'imに用心せよ。奴とその配下のShadowcasterどもは極めて危険だ。Incinerator Gar'imの死の証をMagistrate Solomonのもとへ届けた勇敢な者には、たっぷりと報酬が与えられる。", nil, nil, 0xfbb45123, 0x39291674, 0x74ce327b, nil, nil, "...mm" },
})
